<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
type Config={country:string;product:string;keywords:string;customerType:string;platforms:string[];limit:number}
type Plan={id:string;name:string;config:Config}
type Lead={id:string;name:string;url:string;platform:string;evidence:string;score:number;reasons:string[];status:string;review_note:string;customer_id:string;country:string}
type Task={id:string;status:string;provider:string;message:string;calls_used:number;created_at:string;config:Config;leads?:Lead[];lead_count?:number}
const cfg=ref<Config>({country:'Nigeria',product:'书包、拉杆包三件套',keywords:'school bag set trolley school bag 3 piece school bag set',customerType:'海外中小店主 / 社媒卖家',platforms:['Instagram','Facebook'],limit:20})
const planName=ref('尼日利亚 · 书包与拉杆包三件套'),plans=ref<Plan[]>([]),planId=ref(''),tasks=ref<Task[]>([]),selected=ref<Task>(),provider=ref('manual'),cap=ref({braveConfigured:false,searchEnabled:false}),busy=ref(false),error=ref(''),notice=ref(''),query=ref(''),filter=ref('all'),country=ref('Nigeria'),reviewNote=ref(''),entry=ref({name:'',url:'',evidence:''}),bulk=ref(''),expanded=ref('')
const labels:Record<string,string>={queued:'等待执行',running:'检索中',completed:'检索完成',failed:'执行失败',awaiting_import:'等待 / 持续导入',pending:'待审核',approved:'已入库',rejected:'已排除'}
async function api(path:string,method='GET',body?:unknown){const r=await fetch('/api/discovery/'+path,{method,headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw new Error(d.error||'请求失败');return d}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'连接失败'}finally{busy.value=false}}
async function refresh(){plans.value=await api('plans');tasks.value=await api('tasks');if(selected.value)selected.value=await api('tasks/'+selected.value.id)}
function save(){run(async()=>{const p=await api('plans','POST',{name:planName.value,config:cfg.value});planId.value=p.id;await refresh();notice.value='方案已保存至 MySQL，可重复运行或修改后另存'})}
function choose(){const p=plans.value.find(p=>p.id===planId.value);if(p){cfg.value=structuredClone(p.config);planName.value=p.name}}
function launch(){run(async()=>{selected.value=await api('tasks','POST',{planId:planId.value,provider:provider.value});await refresh();notice.value=provider.value==='manual'?'已创建导入任务，请添加公开店铺主页和证据':'任务已排队，页面会自动更新'})}
function open(t:Task){run(async()=>{selected.value=await api('tasks/'+t.id);country.value=t.config.country;expanded.value='';entry.value={name:'',url:'',evidence:''};bulk.value=''})}
function importEntries(batch=false){run(async()=>{const entries=batch?JSON.parse(bulk.value):[entry.value];if(!Array.isArray(entries))throw new Error('批量内容需为 JSON 数组');const d=await api(`tasks/${selected.value!.id}/import`,'POST',{entries});entry.value={name:'',url:'',evidence:''};bulk.value='';await refresh();notice.value=`新增 ${d.added} 条，跳过重复 ${d.duplicates} 条`})}
function review(l:Lead,action:string){run(async()=>{const d=await api('leads/'+l.id+'/review','POST',{action,note:reviewNote.value,country:country.value});await refresh();notice.value=action==='approve'?`已关联真实 CRM 客户 ${d.customerId}`:'已排除线索并保存原因';reviewNote.value=''})}
function retry(){run(async()=>{await api(`tasks/${selected.value!.id}/retry`,'POST',{});await refresh()})}
function searchUrl(platform:string){const site=({Instagram:'instagram.com',Facebook:'facebook.com',TikTok:'tiktok.com'} as Record<string,string>)[platform];return 'https://www.google.com/search?q='+encodeURIComponent(`site:${site} ${cfg.value.country} ${cfg.value.keywords}`)}
let timer:ReturnType<typeof setInterval>
onMounted(async()=>{await run(async()=>{cap.value=await api('capabilities');await refresh();if(plans.value[0]){planId.value=plans.value[0].id;choose()}});timer=setInterval(async()=>{if(busy.value||!tasks.value.some(t=>['queued','running'].includes(t.status)))return;try{await refresh()}catch{error.value='任务状态更新失败，请刷新重试'}},4000)})
onUnmounted(()=>clearInterval(timer))
</script>
<template>
<div class="discovery-intro panel"><div><span class="tag">真实业务数据 · MySQL</span><h2>从海外小店，发现下一位合作伙伴</h2><p>保存目标 → 发现公开主页 → 核实证据 → 审核入库。当前采用透明规则初筛，不是 AI 已完成背调。</p></div><span class="tag">Nigeria · 书包 / 拉杆包三件套</span></div>
<p v-if="error" class="error" role="alert">{{error}} <button :disabled="busy" @click="run(refresh)">刷新重试</button></p><p v-if="notice" class="notice" role="status">{{notice}}</p><p v-if="busy" role="status">正在保存或读取真实数据…</p>
<div class="discovery-layout"><section class="panel config-panel"><h2>01 · 可复用获客方案</h2><label>选择已保存方案<select v-model="planId" @change="choose"><option value="">新建方案</option><option v-for="p in plans" :value="p.id">{{p.name}}</option></select></label><form @submit.prevent="save"><label>方案名称<input v-model="planName" required maxlength="160"/></label><label>目标国家<input v-model="cfg.country" required maxlength="100"/></label><label>主推产品<input v-model="cfg.product" required maxlength="200"/></label><label>客户类型<input v-model="cfg.customerType" required maxlength="150"/></label><label>英文搜索关键词<textarea v-model="cfg.keywords" required maxlength="250" rows="3"></textarea></label><div class="platforms"><label v-for="p in ['Instagram','Facebook','TikTok']"><input v-model="cfg.platforms" type="checkbox" :value="p"/> {{p}}</label></div><label>每次候选上限<input v-model.number="cfg.limit" type="number" min="1" max="50" required/></label><button :disabled="busy" type="submit">保存为新方案</button></form><hr/><h2>02 · 选择执行方式</h2><label>数据入口<select v-model="provider"><option value="manual">公开搜索辅助 + 主页资料导入</option><option value="brave" :disabled="!cap.braveConfigured||!cap.searchEnabled">Brave 自动检索{{!cap.braveConfigured?'（未配置）':!cap.searchEnabled?'（额度开关未启用）':''}}</option></select></label><p>手动入口不产生搜索 API 费用。自动检索每个平台最多一次请求，每次重试会增加调用；实际计费以服务商为准。</p><button class="primary" :disabled="busy||!planId" @click="launch">创建获客任务 →</button><p>任务使用已保存方案的快照。修改条件后请先另存，再创建任务。</p><div class="search-links"><a v-for="p in cfg.platforms" :href="searchUrl(p)" target="_blank" rel="noopener noreferrer">打开 {{p}} 公开搜索 ↗</a></div></section>
<div><section class="panel"><div class="section-title"><h2>03 · 任务记录</h2><button :disabled="busy" @click="run(refresh)">刷新</button></div><p v-if="!tasks.length">还没有任务，先保存左侧方案，再创建任务。</p><div class="task-list"><button v-for="t in tasks" :key="t.id" :class="{selected:selected?.id===t.id}" :disabled="busy" @click="open(t)"><b>{{t.config.country}} · {{t.config.product}}</b><span>{{labels[t.status]}} · {{t.lead_count||0}} 条 · API {{t.calls_used}} 次</span><small>{{new Date(t.created_at).toLocaleString('zh-CN')}}</small></button></div></section>
<section v-if="selected" class="panel spaced"><div class="section-title"><h2>任务执行与线索审核</h2><span class="tag">{{labels[selected.status]}}</span></div><p>{{selected.message}}</p><p>目标：{{selected.config.country}} · {{selected.config.customerType}}<br/>平台：{{selected.config.platforms.join(' / ')}} · 上限 {{selected.config.limit}} 条 · 累计调用 {{selected.calls_used}} 次</p><button v-if="selected.status==='failed'" :disabled="busy||!cap.searchEnabled" @click="retry">手动重试</button>
<details v-if="selected.provider==='manual'" open class="import-section"><summary>导入实际店铺资料</summary><p>仅粘贴你实际看到的公开信息，系统不会访问链接或自动验证内容真实性。需要具体主页，帖子、视频链接不接受。</p><form @submit.prevent="importEntries()"><label>店铺名称<input v-model="entry.name" maxlength="200" required/></label><label>公开主页链接<input v-model="entry.url" type="url" placeholder="https://www.instagram.com/店铺账号/" required maxlength="1000"/></label><label>公开经营证据<textarea v-model="entry.evidence" rows="3" required maxlength="10000" placeholder="粘贴公开简介、商品内容或经营地区证据；不要填写私人信息"></textarea></label><button :disabled="busy">导入并进行规则初筛</button></form><details class="spaced"><summary>批量 JSON 导入（最多 50 条，受任务上限限制）</summary><p>格式：[ { "name": "店名", "url": "主页链接", "evidence": "公开经营证据" } ]</p><textarea v-model="bulk" rows="5" aria-label="批量线索 JSON"></textarea><button :disabled="busy||!bulk.trim()" @click="importEntries(true)">导入本批资料</button></details></details>
<div class="filters"><input v-model="query" placeholder="搜索店铺、平台或证据" aria-label="筛选线索"/><select v-model="filter"><option value="all">全部线索</option><option value="pending">待审核</option><option value="approved">已入库</option><option value="rejected">已排除</option></select></div>
<p v-if="!selected.leads?.length" class="empty">尚无线索。空结果不会用模拟数据填充。</p><article v-for="l in selected.leads?.filter(l=>(filter==='all'||l.status===filter)&&((l.name+l.platform+l.evidence).toLowerCase().includes(query.toLowerCase())))" :key="l.id" class="prospect-card"><div class="section-title"><div><h2>{{l.name}}</h2><span class="tag">{{l.platform}} · {{labels[l.status]}}</span></div><b class="score">{{l.score}} / 85</b></div><p>地区：{{l.country||'待人工核实'}} · 采购意向：待核实</p><a :href="l.url" target="_blank" rel="noopener noreferrer">查看原始主页 ↗</a><p class="evidence-text">{{l.evidence}}</p><button @click="expanded=expanded===l.id?'':l.id">{{expanded===l.id?'收起':'匹配依据与审核'}}</button><div v-if="expanded===l.id" class="review-area"><p v-for="reason in l.reasons">• {{reason}}</p><p>证据于本任务导入或检索时保存；搜索摘要可能过期，请打开原文核实。三件套组成、MOQ 和价格尚未确认。</p><template v-if="l.status!=='approved'"><label>人工确认国家<input v-model="country" maxlength="100"/></label><label>审核备注 / 排除理由<input v-model="reviewNote" maxlength="500"/></label><button class="primary" :disabled="busy||!country.trim()" @click="review(l,'approve')">确认后导入真实 CRM</button> <button :disabled="busy||!reviewNote.trim()" @click="review(l,'reject')">排除线索</button></template><p v-else>已关联客户：{{l.customer_id}}</p><p v-if="l.review_note">上次审核说明：{{l.review_note}}</p></div></article></section></div></div>
</template>
<style scoped>.discovery-intro{display:flex;justify-content:space-between;align-items:center;gap:20px;background:linear-gradient(110deg,#e3f3eb,#f7e9f1);margin-bottom:22px}.discovery-intro h2{font-size:21px;margin-top:15px}.discovery-layout{display:grid;grid-template-columns:330px minmax(0,1fr);gap:22px}.config-panel{align-self:start}.platforms{display:flex;flex-wrap:wrap;gap:12px}.platforms label{margin:5px 0}.platforms input{display:inline;width:auto}.search-links a{display:block;font-size:11px;margin:13px 0}a{color:#357e73;overflow-wrap:anywhere}.task-list{max-height:280px;overflow:auto}.task-list button{width:100%;text-align:left;display:flex;flex-direction:column;gap:7px;margin-top:10px;font-size:12px}.task-list button span,.task-list small{font-size:10px;color:#6d8479}.task-list .selected{background:#e8f4ed;border-color:#88b5a3}.import-section{background:#f6f9f6;padding:17px;border-radius:6px;margin-top:20px}summary{cursor:pointer;font-size:13px;font-weight:500}.prospect-card{padding:20px 0;border-top:1px solid #e5ece7}.evidence-text{white-space:pre-wrap;overflow-wrap:anywhere;max-height:180px;overflow:auto;background:#f8faf8;padding:12px}.review-area{background:#f6f8f5;padding:15px;margin-top:12px}.error{background:#fce8ee;color:#993a56;padding:14px}hr{border:0;border-top:1px solid #e5ece7;margin:25px 0}@media(max-width:1100px){.discovery-layout{grid-template-columns:1fr}.discovery-intro{align-items:flex-start;flex-direction:column}}
</style>
